import{_ as a,o as l,c as o,ai as t}from"./chunks/framework.DAbPic9L.js";const u=JSON.parse('{"title":"数字万用表","description":"","frontmatter":{},"headers":[],"relativePath":"repair/multimeter.md","filePath":"repair/multimeter.md","lastUpdated":1783097192000}'),i={name:"repair/multimeter.md"};function d(r,e,p,c,s,n){return l(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="数字万用表" tabindex="-1">数字万用表 <a class="header-anchor" href="#数字万用表" aria-label="Permalink to &quot;数字万用表&quot;">​</a></h1><h2 id="基础常识" tabindex="-1">基础常识 <a class="header-anchor" href="#基础常识" aria-label="Permalink to &quot;基础常识&quot;">​</a></h2><ul><li><p>万用表作用: 用于测试负载(元器件、家电设备)的好坏情况。<span class="text-red">特别注意: 在交流电使用场景请务必谨慎小心</span>。</p></li><li><p>二笔四孔: <span class="text-red">红笔代表正极、黑笔代表负极</span>。<span class="text-red">黑笔端连接<code>COM</code>孔位</span>，红笔格局不同场景插入到<code>VΩ</code>、<code>mA</code>、<code>A</code>等孔位。</p></li><li><p>孔位场景: <code>VΩ</code>测试负载电压电阻场景、<code>mA</code>测试负载小电流场景、<code>A</code>测试负载大电流刺激。</p></li><li><p>量程控制: <span class="text-red">遵循大量程优先，避免短路、过载损害万用表</span>；稍调整量程，测场景细节。</p></li></ul><h2 id="蜂鸣档-hz" tabindex="-1">蜂鸣档(<code>Hz</code>) <a class="header-anchor" href="#蜂鸣档-hz" aria-label="Permalink to &quot;蜂鸣档(`Hz`)&quot;">​</a></h2><p><b class="text-red">特别注意: 严禁带电操作；即断电再测试</b>。</p><p><b class="text-red">红黑笔孔位: 黑笔端连接<code>COM</code>孔位，红笔端连接<code>VΩ</code>孔位</b>。</p><p><b class="text-red">核心测试点: 测通断情况</b>。</p><br><p><strong>应用场景</strong></p><ul><li><p>电缆导线排查</p><ul><li><p>寻线编号: 在多芯电缆中确认同一根线（蜂鸣代表同一根）。</p></li><li><p>断线定位: 检查电源线内部断路情况（不响响代表断路）。</p></li></ul></li><li><p>电子元件检测</p><ul><li><p>按钮开关: 闭合时蜂鸣，断开时不响。</p></li><li><p>二/三极管: 遵循<code>单向导通，反向截止</code>原则，正常则蜂鸣，短路、击穿则不响。</p></li><li><p>继电器触点粘接情况: 正常情况，常开蜂鸣，常关不响。</p></li></ul></li><li><p>PCB 电路板检测</p><ul><li>检测电路板元器件相邻引脚是否搭锡短路。</li></ul></li></ul><br><p><strong>操作流程</strong></p><ol><li><p>切断电源: 拔掉电器插头、拆下蓄电池。</p></li><li><p>档位正确: 红黑笔端孔位插入正确，转盘拨到蜂鸣档位（<code>Hz</code>）；再开始测量。</p></li></ol><h2 id="电阻档-ω" tabindex="-1">电阻档(<code>Ω</code>) <a class="header-anchor" href="#电阻档-ω" aria-label="Permalink to &quot;电阻档(`Ω`)&quot;">​</a></h2><p><b class="text-red">特别注意: 严禁带电操作；即断电再测试</b>。</p><p><b class="text-red">红黑笔孔位: 黑笔端连接<code>COM</code>孔位，红笔端连接<code>VΩ</code>孔位</b>。</p><p><b class="text-red">核心测试点: 测通断、线圈、阻值等情况</b>。</p><br><p><strong>应用场景</strong></p><ul><li><p>电路通断情况: <code>电阻阻值 &gt; 0 ? 电路正常 : 电路未通</code>。</p></li><li><p>检测线圈情况</p><ul><li><p>导线断路: <code>电阻阻值 === (OL | 1) ? 断路｜开路 : 正常</code>。</p></li><li><p>匝间短路: <code>电阻阻值接近 0 或远低于正常参考值 ? 局部短路(过热包漆线融化) : 正常</code>。</p></li><li><p>漏电、对地短路: 包漆线与负载外壳碰撞发生短路。</p></li></ul></li><li><p>电动机好坏情况: <code>电阻阻值 &gt; 0.5MΩ ? 电机正常 : 电机损坏</code>。</p></li></ul><br><p><strong>操作流程</strong></p><ol><li><p>切断电源: 拔掉电器插头、拆下蓄电池。</p></li><li><p>电容放电: 电路板的电容短接碰一下，防止电容残留高压。</p></li><li><p>断开单端: 元件电阻单独测试时，需要断开单端；否则并联的元件会干扰测试值。</p></li><li><p>档位正确: 红黑笔端孔位插入正确，转盘拨到电阻档位（<code>Ω</code>）；再开始测量。</p></li></ol><h2 id="电容档-f" tabindex="-1">电容档(<code>F</code>) <a class="header-anchor" href="#电容档-f" aria-label="Permalink to &quot;电容档(`F`)&quot;">​</a></h2><h2 id="直流电压档-v" tabindex="-1">直流电压档(<code>V-</code>) <a class="header-anchor" href="#直流电压档-v" aria-label="Permalink to &quot;直流电压档(`V-`)&quot;">​</a></h2><p><b class="text-red">特别注意: 测试直流电压档，必须区分正负极，避免短路损坏元器件。</b>。</p><h2 id="直流电流档-a" tabindex="-1">直流电流档(<code>A-</code>) <a class="header-anchor" href="#直流电流档-a" aria-label="Permalink to &quot;直流电流档(`A-`)&quot;">​</a></h2><h2 id="交流电压档-v" tabindex="-1">交流电压档(<code>V~</code>) <a class="header-anchor" href="#交流电压档-v" aria-label="Permalink to &quot;交流电压档(`V~`)&quot;">​</a></h2><h2 id="交流电流档-a" tabindex="-1">交流电流档(<code>A~</code>) <a class="header-anchor" href="#交流电流档-a" aria-label="Permalink to &quot;交流电流档(`A~`)&quot;">​</a></h2>',29)])])}const b=a(i,[["render",d]]);export{u as __pageData,b as default};
